    public static function isCountry(int $id): bool
    {
        return isset(self::COUNTRY_NAMES[$id]);
    }

    public static function isLanguage(string $code): bool
    {
        return isset(self::LANGUAGES[$code]);
    }

    /** The language Google Ads volumes are filtered by, or null to ask for the country alone. */
    public static function adsLanguage(string $code): ?string
    {
        return in_array($code, self::ADS_LANGUAGES, true) ? $code : null;
    }

    /** Whether DataForSEO Labs (keyword research, ranked keywords, competitors) has data for the market. */
    public static function labsSupports(int $country, string $language): bool
    {
        return in_array($language, self::LABS[$country] ?? [], true);
    }

    /** Why a market cannot be researched with DataForSEO Labs, naming the languages its country can be; null when it can. */
    public static function labsProblem(int $country, string $language): ?string
    {
        if (self::labsSupports($country, $language)) {
            return null;
        }
        $name = self::COUNTRY_NAMES[$country] ?? (string) $country;
        $suggested = array_map(static fn(string $code): string => self::LANGUAGES[$code] ?? $code, self::suggested($country));

        return $suggested === []
            ? sprintf('DataForSEO keyword research has no data for %s. Choose another country for this lookup.', $name)
            : sprintf('DataForSEO keyword research has no data for %s in %s. Choose %s.', $name, self::LANGUAGES[$language] ?? $language, implode(' or ', $suggested));
    }

    /** LABS as JSON for the market selects (public/assets/js/market-select.js). */
    public static function labsJson(): string
    {
        return json_encode(self::LABS, JSON_THROW_ON_ERROR);
    }

    /** The code DataForSEO Labs expects for a catalog language. */
    public static function labsLanguage(string $code): string
    {
        return $code === 'no' ? 'nb' : $code;
    }

    /**
     * The languages to offer first for a country: those DataForSEO Labs has
     * data for, in its order; empty when Labs does not cover the country.
     *
     * @return list<string>
     */
    public static function suggested(int $country): array
    {
        return self::LABS[$country] ?? [];
    }
}
